// Apartments sharing a clearing group are one unit: one report, one email, one
// payment. Stage state lives on the first member; members lists every apartment
// so the counters still speak in apartments.
function apts() {
  var raw = (S.apts || []).filter(function (a) { return a && a.name && FLOWS[a.profile]; })
    .sort(function (x, y) { return String(x.name).localeCompare(String(y.name)); });
  var byKey = {}, order = [];
  raw.forEach(function (a) {
    var g = String(a.clearGroup || '').trim();
    var key = g ? 'g:' + g.toLowerCase() : 'a:' + a.id;
    if (!byKey[key]) {
      byKey[key] = { id: String(a.id), name: g || a.name, type: a.profile,
        area: (a.aliases || '') || '', owner: ((a.ownerName || '') + ' ' + (a.ownerSurname || '')).trim(),
        group: g, members: [] };
      order.push(key);
    }
    byKey[key].members.push(String(a.id));
  });
  return order.map(function (k) { var u = byKey[k];
    if (u.members.length > 1) u.name = u.group + ' (' + u.members.length + ' apartments)'; return u; });
}

